INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2271129, 313334, 41337, '<td valign="top">Bold colors. The initial impact was very good for me. Technically speaking, I don''t like halos and I wished maybe you didn''t include the out of focus part in the upper right corner. Those would be my only nitpicks.</td>', 'Bold colors. The initial impact was very good for me. Technically speaking, I don''t like halos and I wished maybe you didn''t include the out of focus part in the upper right corner. Those would be my only nitpicks.', '2006-03-29 18:16:02.000000', NULL, 1),
