(2273114, 313146, 4551, '<td valign="top">I''ll bet you are saying, "I wish I has removed tha hair!" Interesting shape and design. I have no idea what this is. Nice color and tonal gradation.</td>', 'I''ll bet you are saying, "I wish I has removed tha hair!" Interesting shape and design. I have no idea what this is. Nice color and tonal gradation.', '2006-03-30 11:18:25.000000', NULL, 1),
(2273115, 312394, 4551, '<td valign="top">Hmmmm. Pepper corns on salt? I can almost envision a snowman made from this material. Difficult to capture good focus here.</td>', 'Hmmmm. Pepper corns on salt? I can almost envision a snowman made from this material. Difficult to capture good focus here.', '2006-03-30 11:19:44.000000', NULL, 1),
(2273117, 313339, 4551, '<td valign="top">Nice abstract of a set of scissors. Good shadow detail and sharpness.</td>', 'Nice abstract of a set of scissors. Good shadow detail and sharpness.', '2006-03-30 11:20:24.000000', NULL, 1),
(2273118, 312403, 4551, '<td valign="top">At first it looked like edges of old books or journals but now I see what it is. Nice, simple abstraction.</td>', 'At first it looked like edges of old books or journals but now I see what it is. Nice, simple abstraction.', '2006-03-30 11:21:29.000000', NULL, 1),
(2273119, 312810, 4551, '<td valign="top">Good eye to see the art form here. Would have preferred a little more offset cropping. Nice color and tonal gradation,</td>', 'Good eye to see the art form here. Would have preferred a little more offset cropping. Nice color and tonal gradation,', '2006-03-30 11:22:33.000000', NULL, 1),
(2273121, 312698, 4551, '<td valign="top">You have a good eye for abstract design. Nice work.</td>', 'You have a good eye for abstract design. Nice work.', '2006-03-30 11:23:42.000000', NULL, 1),
(2273124, 311539, 4551, '<td valign="top">Nice use of the flames to create this random pattern and abstract design.</td>', 'Nice use of the flames to create this random pattern and abstract design.', '2006-03-30 11:24:24.000000', NULL, 1),
(2273127, 310932, 4551, '<td valign="top">Very nice design work,. You have a good eye. I like the use of the colors in the background. You obviously put some time and effort into this piece.</td>', 'Very nice design work,. You have a good eye. I like the use of the colors in the background. You obviously put some time and effort into this piece.', '2006-03-30 11:25:36.000000', NULL, 1),
(2273131, 311660, 4551, '<td valign="top">Very nice use of color to make this one standout from similar ideas. You are very creative.</td>', 'Very nice use of color to make this one standout from similar ideas. You are very creative.', '2006-03-30 11:26:25.000000', NULL, 1),
(2273133, 310505, 4551, '<td valign="top">I like the use of green reflections to contrast with the red cords.</td>', 'I like the use of green reflections to contrast with the red cords.', '2006-03-30 11:26:59.000000', NULL, 1),
(2273135, 312436, 52790, '<td valign="top">i don''t know what camera you used, but my guess is that it doesn''t have manual focus. it ruined this shot</td>', 'i don''t know what camera you used, but my guess is that it doesn''t have manual focus. it ruined this shot', '2006-03-30 11:27:38.000000', NULL, 1),
(2273138, 311578, 4551, '<td valign="top">I think closer cropping would make this a stronger image if you eliminate the ''target'' design and shape. Lots of good textures and color waiting a little closer in. Good eye.</td>', 'I think closer cropping would make this a stronger image if you eliminate the ''target'' design and shape. Lots of good textures and color waiting a little closer in. Good eye.', '2006-03-30 11:28:46.000000', NULL, 1),
(2273140, 312676, 4551, '<td valign="top">The dart may have had better visibility against the lighter sector. Interesting viewpoint.</td>', 'The dart may have had better visibility against the lighter sector. Interesting viewpoint.', '2006-03-30 11:29:28.000000', NULL, 1),
(2273142, 312272, 4551, '<td valign="top">Good sharpness and tonal gradation. Interesting design.</td>', 'Good sharpness and tonal gradation. Interesting design.', '2006-03-30 11:30:30.000000', NULL, 1),
(2273143, 311571, 4551, '<td valign="top">I like the use of the droplets and color on this one. Hope you will describe the process in the notes section. Well done!</td>', 'I like the use of the droplets and color on this one. Hope you will describe the process in the notes section. Well done!', '2006-03-30 11:31:23.000000', NULL, 1),
(2273145, 312587, 4551, '<td valign="top">Good eye for the texture patterns. A little grayed out on my monitor though.</td>', 'Good eye for the texture patterns. A little grayed out on my monitor though.', '2006-03-30 11:32:47.000000', NULL, 1),
(2273147, 311333, 4551, '<td valign="top">Good use of lighting. Excellent sharpness and tonal range.</td>', 'Good use of lighting. Excellent sharpness and tonal range.', '2006-03-30 11:33:25.000000', NULL, 1),
(2273148, 311848, 4551, '<td valign="top">An amazing collection of colors. I like it!</td>', 'An amazing collection of colors. I like it!', '2006-03-30 11:33:55.000000', NULL, 1),
(2273150, 310361, 4551, '<td valign="top">Good eye for the abstract in this coil.</td>', 'Good eye for the abstract in this coil.', '2006-03-30 11:34:29.000000', NULL, 1),
(2273152, 312394, 37719, '<td valign="top">Hmm....sea salt and peppercorns...very reminiscent...nice focus and good DoF control.  Lighting is well done also.  Compositionally I am thinking a few less peppercorns in the background, but they don''t hurt the image.  It is just that the three in the foregroiund make a strong presence without the ones behind them.  Nice job!</td>', 'Hmm....sea salt and peppercorns...very reminiscent...nice focus and good DoF control.  Lighting is well done also.  Compositionally I am thinking a few less peppercorns in the background, but they don''t hurt the image.  It is just that the three in the foregroiund make a strong presence without the ones behind them.  Nice job!', '2006-03-30 11:34:59.000000', NULL, 1),
(2273154, 313306, 4551, '<td valign="top">I never realized there were so many hues here. White background is a little distracting. Good eye!</td>', 'I never realized there were so many hues here. White background is a little distracting. Good eye!', '2006-03-30 11:35:23.000000', NULL, 1),
(2273158, 311200, 4551, '<td valign="top">Nice use of the water droplets on this piece of vegetation.</td>', 'Nice use of the water droplets on this piece of vegetation.', '2006-03-30 11:35:49.000000', NULL, 1),
(2273160, 312751, 4551, '<td valign="top">Excellent sharpness and color contrasts. I wish the cropping wasn''t so dead-center, though. Nice work.</td>', 'Excellent sharpness and color contrasts. I wish the cropping wasn''t so dead-center, though. Nice work.', '2006-03-30 11:36:47.000000', NULL, 1),
(2273161, 311639, 4551, '<td valign="top">Nice tonal gradations. A little small though.</td>', 'Nice tonal gradations. A little small though.', '2006-03-30 11:37:08.000000', NULL, 1),
(2273163, 312893, 4551, '<td valign="top">Good sharpness. May want to crop a little more off the bottom to lower the ''weight''f the point of interest. . Nice work.</td>', 'Good sharpness. May want to crop a little more off the bottom to lower the ''weight''f the point of interest. . Nice work.', '2006-03-30 11:38:34.000000', NULL, 1),
(2273167, 311356, 4551, '<td valign="top">Good use of contrasting colors. You took the time to put some thought into this composition. Nice work.</td>', 'Good use of contrasting colors. You took the time to put some thought into this composition. Nice work.', '2006-03-30 11:39:49.000000', NULL, 1),
(2273169, 312996, 4551, '<td valign="top">Interesting mix of color and textures. The white powery dusting tends to distract somewhat.</td>', 'Interesting mix of color and textures. The white powery dusting tends to distract somewhat.', '2006-03-30 11:40:49.000000', NULL, 1),
(2273172, 311562, 4551, '<td valign="top">Looks like some of the clockworks I have encountered. Good eye for the abstract. Sharp where it needs to be. Nice work.</td>', 'Looks like some of the clockworks I have encountered. Good eye for the abstract. Sharp where it needs to be. Nice work.', '2006-03-30 11:42:14.000000', NULL, 1),
(2273181, 311622, 32084, '<td valign="top">This is a great shot.  In my opinion it needs a little more contrast to seperate the edges, define the texture and really make it POP.  Good artistic shot though.</td>', 'This is a great shot.  In my opinion it needs a little more contrast to seperate the edges, define the texture and really make it POP.  Good artistic shot though.', '2006-03-30 11:50:44.000000', NULL, 1),
(2273193, 312720, 46885, '<td valign="top">gees, that''s lipstick?</td>', 'gees, that''s lipstick?', '2006-03-30 12:05:05.000000', NULL, 1),
(2273198, 313170, 43516, '<td valign="top">It could use some sharpness/focus.</td>', 'It could use some sharpness/focus.', '2006-03-30 12:06:29.000000', NULL, 1),
(2273202, 313304, 46885, '<td valign="top">balls :) more sharpness wouldn''t hurt</td>', 'balls :) more sharpness wouldn''t hurt', '2006-03-30 12:08:17.000000', NULL, 1),
(2273212, 313140, 43516, '<td valign="top">Very nice use of lines</td>', 'Very nice use of lines', '2006-03-30 12:14:25.000000', NULL, 1),
(2273228, 313086, 46885, '<td valign="top">absract? hardly.</td>', 'absract? hardly.', '2006-03-30 12:21:06.000000', NULL, 1),
(2273231, 313104, 43516, '<td valign="top">I think it could use more sharpness, but very nice composition!</td>', 'I think it could use more sharpness, but very nice composition!', '2006-03-30 12:23:07.000000', NULL, 1),
(2273277, 312947, 52790, '<td valign="top">my favorite</td>', 'my favorite', '2006-03-30 12:45:38.000000', NULL, 1),
(2273316, 313314, 49865, '<td valign="top">i did a photo like this once for backlighting. i like the blue color in this one.</td>', 'i did a photo like this once for backlighting. i like the blue color in this one.', '2006-03-30 12:59:20.000000', NULL, 1),
(2273334, 312552, 43405, '<td valign="top">Nice thought, and good composition. I think however that the small soze of the photograph may count against you. <a href="//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">Maybe this will help</a></td>', 'Nice thought, and good composition. I think however that the small soze of the photograph may count against you. Maybe this will help', '2006-03-30 13:07:15.000000', NULL, 1),
(2273337, 313032, 43405, '<td valign="top">Great colours, and composition. Should do well, I should think.</td>', 'Great colours, and composition. Should do well, I should think.', '2006-03-30 13:08:19.000000', NULL, 1),
(2273348, 312454, 18870, '<td valign="top">Very clever title and cool idea. well composed too!</td>', 'Very clever title and cool idea. well composed too!', '2006-03-30 13:14:13.000000', NULL, 1),
(2273362, 313086, 48954, '<td valign="top">cool macro, but not very abstract</td>', 'cool macro, but not very abstract', '2006-03-30 13:19:47.000000', NULL, 1),
(2273383, 313234, 7322, '<td valign="top">There isn''t enough sharp detail and the strong glare on the vinyl is a detraction more than a design feature, in my opinion. There just isn''t enough going on here to grab my interest.</td>', 'There isn''t enough sharp detail and the strong glare on the vinyl is a detraction more than a design feature, in my opinion. There just isn''t enough going on here to grab my interest.', '2006-03-30 13:32:18.000000', NULL, 1),
(2273406, 313140, 37103, '<td valign="top">I really love this one.  You picked such a simple subject and it makes such a beautiful photo.  The textures and colors are great.  The only distraction is that teeny piece of black in the center.</td>', 'I really love this one.  You picked such a simple subject and it makes such a beautiful photo.  The textures and colors are great.  The only distraction is that teeny piece of black in the center.', '2006-03-30 13:41:25.000000', NULL, 1),
(2273432, 312587, 42135, '<td valign="top">Someone''s heel :)</td>', 'Someone''s heel :)', '2006-03-30 13:49:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2273577, 313300, 54256, '<td valign="top">It''s a little too soft for my taste.  I think with a really shallow DOF you could have maintained the ethereal border, but sharpened up the middle.  Still a good shot, though.</td>', 'It''s a little too soft for my taste.  I think with a really shallow DOF you could have maintained the ethereal border, but sharpened up the middle.  Still a good shot, though.', '2006-03-30 14:43:49.000000', NULL, 1),
