(2276308, 312394, 42495, '<td valign="top">Clever.  Would have been better if pepper were a bit brighter.</td>', 'Clever.  Would have been better if pepper were a bit brighter.', '2006-03-31 12:02:36.000000', NULL, 1),
(2276316, 312931, 34134, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2006-03-31 12:07:26.000000', NULL, 1),
(2276322, 309980, 22922, '<td valign="top">Focus is very important in Macro photography; this looks more like a painting than a photograph. As a painting, I love it. As a photo, I don''t.</td>', 'Focus is very important in Macro photography; this looks more like a painting than a photograph. As a painting, I love it. As a photo, I don''t.', '2006-03-31 12:13:58.000000', NULL, 1),
(2276323, 311660, 42495, '<td valign="top">I wouldn''t have guessed this one.</td>', 'I wouldn''t have guessed this one.', '2006-03-31 12:14:43.000000', NULL, 1),
(2276325, 312436, 42495, '<td valign="top">In focus would be much better.</td>', 'In focus would be much better.', '2006-03-31 12:15:40.000000', NULL, 1),
(2276330, 312682, 22922, '<td valign="top">Not sure if you know how to resize photos. Take your photos at the largest size your camera supports. In Photoshop, go to "Image Size" and make sure "Constrain Proportions" is checked, then change the longest side to 640 pixels. Then go to "Save for Web" and "Optimize to File Size" and enter 150K. Save and you''re all set.</td>', 'Not sure if you know how to resize photos. Take your photos at the largest size your camera supports. In Photoshop, go to "Image Size" and make sure "Constrain Proportions" is checked, then change the longest side to 640 pixels. Then go to "Save for Web" and "Optimize to File Size" and enter 150K. Save and you''re all set.', '2006-03-31 12:18:36.000000', NULL, 1),
(2276335, 311789, 42495, '<td valign="top">Meets the challenge well.</td>', 'Meets the challenge well.', '2006-03-31 12:20:58.000000', NULL, 1),
(2276340, 312907, 22922, '<td valign="top">Nice image and concept, I''d darken the image a bit, though, it''s blown out around the edges and the nose would look better in a lower key image.</td>', 'Nice image and concept, I''d darken the image a bit, though, it''s blown out around the edges and the nose would look better in a lower key image.', '2006-03-31 12:25:39.000000', NULL, 1),
(2276345, 311868, 13759, '<td valign="top">It´s a good picture but is not so abstract as I expect. One can easely realise what it is.</td>', 'It´s a good picture but is not so abstract as I expect. One can easely realise what it is.', '2006-03-31 12:29:27.000000', NULL, 1),
(2276346, 313335, 13759, '<td valign="top">Cheese? Whow! I´m bit crazy for cheese... Good picture!</td>', 'Cheese? Whow! I´m bit crazy for cheese... Good picture!', '2006-03-31 12:31:02.000000', NULL, 1),
