INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2276492, 312541, 54747, '<td valign="top">far too blurry to draw my eye.  Nice colors, though.</td>', 'far too blurry to draw my eye.  Nice colors, though.', '2006-03-31 13:51:19.000000', NULL, 1),
(2276494, 311580, 54747, '<td valign="top">nice light and shadow.</td>', 'nice light and shadow.', '2006-03-31 13:51:36.000000', NULL, 1),
