(2276527, 310261, 53571, '<td valign="top">This would be a stronger photograph if you presented it as it was taken in my opinion</td>', 'This would be a stronger photograph if you presented it as it was taken in my opinion', '2006-03-31 14:01:11.000000', NULL, 1),
(2276556, 312763, 55949, '<td valign="top">Wicked. Nice focus.</td>', 'Wicked. Nice focus.', '2006-03-31 14:11:05.000000', NULL, 1),
(2276558, 313284, 55949, '<td valign="top">Nice lighting and the water is nice.</td>', 'Nice lighting and the water is nice.', '2006-03-31 14:11:58.000000', NULL, 1),
(2276559, 312994, 55949, '<td valign="top">I like the simplicity of this.  I initially thought I was looking at the dome roof of a building.</td>', 'I like the simplicity of this.  I initially thought I was looking at the dome roof of a building.', '2006-03-31 14:12:38.000000', NULL, 1),
(2276562, 313086, 27562, '<td valign="top">I don''t think it meets the challenge very well, but who cares it''s dam good.  Great point of focus, excellent lighting and non distracting background. 9 and worth every point.</td>', 'I don''t think it meets the challenge very well, but who cares it''s dam good.  Great point of focus, excellent lighting and non distracting background. 9 and worth every point.', '2006-03-31 14:13:45.000000', NULL, 1),
(2276564, 312077, 55949, '<td valign="top">The worn and dinginess are and interesting mix of textures.  I love the different covers that con be found in different cities and countries.  I have been taking photos of these for years.</td>', 'The worn and dinginess are and interesting mix of textures.  I love the different covers that con be found in different cities and countries.  I have been taking photos of these for years.', '2006-03-31 14:14:04.000000', NULL, 1),
(2276569, 311728, 55949, '<td valign="top">The cords on the left side are distracting.  Great focus on the tools.  I initially thought they were levers.</td>', 'The cords on the left side are distracting.  Great focus on the tools.  I initially thought they were levers.', '2006-03-31 14:15:10.000000', NULL, 1),
(2276570, 311510, 54747, '<td valign="top">The lack of bright colors at the top detract from the overall composition.  Perhaps if you had drawn out those colors more to make the entire shot well-saturated?</td>', 'The lack of bright colors at the top detract from the overall composition.  Perhaps if you had drawn out those colors more to make the entire shot well-saturated?', '2006-03-31 14:15:15.000000', NULL, 1),
(2276571, 312855, 54747, '<td valign="top">the blue element at the bottom right is somewhat distracting.  Great colors otherwise, though.</td>', 'the blue element at the bottom right is somewhat distracting.  Great colors otherwise, though.', '2006-03-31 14:15:58.000000', NULL, 1),
(2276578, 313261, 55949, '<td valign="top">Neat photo.  I like the radial lines.  The position helps make the mind think of a seashell.  The colors are pleasant</td>', 'Neat photo.  I like the radial lines.  The position helps make the mind think of a seashell.  The colors are pleasant', '2006-03-31 14:18:18.000000', NULL, 1),
(2276579, 312990, 55949, '<td valign="top">I thought of this too.  Interesting board.</td>', 'I thought of this too.  Interesting board.', '2006-03-31 14:18:46.000000', NULL, 1),
(2276581, 311323, 53964, '<td valign="top">I''d like it much better without the product name.</td>', 'I''d like it much better without the product name.', '2006-03-31 14:19:03.000000', NULL, 1),
(2276585, 313086, 22748, '<td valign="top">Cool picture, but not very abstract, the subject is easily identified.</td>', 'Cool picture, but not very abstract, the subject is easily identified.', '2006-03-31 14:19:41.000000', NULL, 1),
(2276587, 311420, 55949, '<td valign="top">I like the color range of the blue.</td>', 'I like the color range of the blue.', '2006-03-31 14:20:03.000000', NULL, 1),
(2276592, 311864, 22748, '<td valign="top">wow! so close</td>', 'wow! so close', '2006-03-31 14:21:57.000000', NULL, 1),
(2276595, 311852, 55949, '<td valign="top">Nice tight color.  The writing on one cord is somewhat distracting.  The uniform lights are competing.  Maybe the cords should have been in focus too.<br/>I love this photographer.</td>', 'Nice tight color.  The writing on one cord is somewhat distracting.  The uniform lights are competing.  Maybe the cords should have been in focus too.I love this photographer.', '2006-03-31 14:23:08.000000', NULL, 1),
(2276596, 311503, 53964, '<td valign="top">Love the "watercolour" feeling.</td>', 'Love the "watercolour" feeling.', '2006-03-31 14:23:12.000000', NULL, 1),
(2276603, 310907, 55949, '<td valign="top">The tight focus is super.  I love the green and blue background.</td>', 'The tight focus is super.  I love the green and blue background.', '2006-03-31 14:25:08.000000', NULL, 1),
(2276607, 311465, 55949, '<td valign="top">Not abstract enough for my taste and a bit blurry.</td>', 'Not abstract enough for my taste and a bit blurry.', '2006-03-31 14:25:52.000000', NULL, 1),
