(2276808, 312881, 42495, '<td valign="top">Abstract, macro, and technically well done.  One of the better ones of the challenge.</td>', 'Abstract, macro, and technically well done.  One of the better ones of the challenge.', '2006-03-31 15:59:50.000000', NULL, 1),
