(2276882, 313144, 42495, '<td valign="top">Not really abstract.</td>', 'Not really abstract.', '2006-03-31 16:52:17.000000', NULL, 1),
(2276883, 313223, 42495, '<td valign="top">I have no idea what this is.  And that''s the point!</td>', 'I have no idea what this is.  And that''s the point!', '2006-03-31 16:52:50.000000', NULL, 1),
(2276885, 311752, 42495, '<td valign="top">Neat picture, but not macro.</td>', 'Neat picture, but not macro.', '2006-03-31 16:54:22.000000', NULL, 1),
(2276919, 310702, 4551, '<td valign="top">The thumbnail caused me to have a closer look but unfortunately the larger image appeared a bit soft. Nice composition and tonal range. You held detail in the whites particularly well. Too bad it wasn''t a bit sharper.</td>', 'The thumbnail caused me to have a closer look but unfortunately the larger image appeared a bit soft. Nice composition and tonal range. You held detail in the whites particularly well. Too bad it wasn''t a bit sharper.', '2006-03-31 17:11:40.000000', NULL, 1),
(2276922, 312774, 4551, '<td valign="top">Good eye for composition and the use of shadows. Sharp where it counts. Nice work.</td>', 'Good eye for composition and the use of shadows. Sharp where it counts. Nice work.', '2006-03-31 17:12:30.000000', NULL, 1),
(2276930, 313147, 4551, '<td valign="top">I always admire folks who can see a picture in a scene that most others would pass by. The cropping leaves a bit of dead space on the left that doesn''t really add to the effect of the image . Good eye.</td>', 'I always admire folks who can see a picture in a scene that most others would pass by. The cropping leaves a bit of dead space on the left that doesn''t really add to the effect of the image . Good eye.', '2006-03-31 17:13:57.000000', NULL, 1),
(2276934, 312915, 4551, '<td valign="top">Nice use of the texture in the flint wheel. You held shadow detail where needed. Background complements subject and is not distracting.</td>', 'Nice use of the texture in the flint wheel. You held shadow detail where needed. Background complements subject and is not distracting.', '2006-03-31 17:15:49.000000', NULL, 1),
(2276935, 312436, 19959, '<td valign="top">Sorry, this is out of focus.</td>', 'Sorry, this is out of focus.', '2006-03-31 17:15:53.000000', NULL, 1),
(2276937, 313308, 4551, '<td valign="top">I like the way you used refraction of the light through the insulator to add another dimension to your image. Good job.</td>', 'I like the way you used refraction of the light through the insulator to add another dimension to your image. Good job.', '2006-03-31 17:17:15.000000', NULL, 1),
(2276940, 312715, 4551, '<td valign="top">Refraction of light really does wonders here. You have a good eye to see the results of this refraction and capture it digitally. Nice color and tonal range.</td>', 'Refraction of light really does wonders here. You have a good eye to see the results of this refraction and capture it digitally. Nice color and tonal range.', '2006-03-31 17:18:24.000000', NULL, 1),
(2276942, 313146, 19959, '<td valign="top">Nice idea, hair is distracting though</td>', 'Nice idea, hair is distracting though', '2006-03-31 17:19:18.000000', NULL, 1),
(2276943, 312578, 4551, '<td valign="top">The thumbnail caught my eye so I thought I''d have a closer look. Too bad it isn''t a bit sharper. Nice use of colors and pleasing composition.</td>', 'The thumbnail caught my eye so I thought I''d have a closer look. Too bad it isn''t a bit sharper. Nice use of colors and pleasing composition.', '2006-03-31 17:19:43.000000', NULL, 1),
(2276944, 313104, 4551, '<td valign="top">As a clockmaker, these kinds of shots always grab my attention. Nice use of the blue highlights on the metal.</td>', 'As a clockmaker, these kinds of shots always grab my attention. Nice use of the blue highlights on the metal.', '2006-03-31 17:20:50.000000', NULL, 1),
(2276946, 312544, 4551, '<td valign="top">Very nice use of shading and tonal range. Excellent sharpness and composition. Good eye.</td>', 'Very nice use of shading and tonal range. Excellent sharpness and composition. Good eye.', '2006-03-31 17:21:31.000000', NULL, 1),
(2276949, 312837, 4551, '<td valign="top">Very interesting and unusual colors. I saw a similar framed shot in monochrome in a garden center today with a big pricetag for decoration one''s home. Good eye. Nice work.</td>', 'Very interesting and unusual colors. I saw a similar framed shot in monochrome in a garden center today with a big pricetag for decoration one''s home. Good eye. Nice work.', '2006-03-31 17:22:44.000000', NULL, 1),
(2276954, 311903, 4551, '<td valign="top">The message is "Your wax job is working."  Nice capture of these water drops. The drift out of focus is a bit distracting but you have a good eye to see art in such a place.</td>', 'The message is "Your wax job is working."  Nice capture of these water drops. The drift out of focus is a bit distracting but you have a good eye to see art in such a place.', '2006-03-31 17:24:38.000000', NULL, 1),
(2276958, 313136, 4551, '<td valign="top">Not sure what this is but you have a good eye for the abstract. Perhaps you will let us in on theh subject in your photo notes at the end of the composition.</td>', 'Not sure what this is but you have a good eye for the abstract. Perhaps you will let us in on theh subject in your photo notes at the end of the composition.', '2006-03-31 17:27:11.000000', NULL, 1),
(2276963, 312838, 4551, '<td valign="top">Nice use of the refraction of light through the glass. Can you share what the background was made from? Nice work.</td>', 'Nice use of the refraction of light through the glass. Can you share what the background was made from? Nice work.', '2006-03-31 17:28:28.000000', NULL, 1),
(2276965, 313037, 4551, '<td valign="top">A little hot in places but you have a good eye for seeing the play of light and shadows.</td>', 'A little hot in places but you have a good eye for seeing the play of light and shadows.', '2006-03-31 17:29:08.000000', NULL, 1),
(2276969, 311580, 4551, '<td valign="top">Interesting use of the hands of a clock. Too bad the sharpness didn''t carry throughout the hands. Good use of shadows and composition.</td>', 'Interesting use of the hands of a clock. Too bad the sharpness didn''t carry throughout the hands. Good use of shadows and composition.', '2006-03-31 17:30:30.000000', NULL, 1),
(2276970, 313171, 4551, '<td valign="top">Good eye for seeing beauty in a common item that most would bypass. A little soft in places but the flow of the wires provides a nice composition.</td>', 'Good eye for seeing beauty in a common item that most would bypass. A little soft in places but the flow of the wires provides a nice composition.', '2006-03-31 17:31:45.000000', NULL, 1),
(2276973, 311868, 4551, '<td valign="top">As a clockmaker I have seen these spring barrels many times. I agree with the title that as composed this clock would not run.  8-)<br/> Good use of common parts to create a pleasing and interesting composition.</td>', 'As a clockmaker I have seen these spring barrels many times. I agree with the title that as composed this clock would not run.  8-) Good use of common parts to create a pleasing and interesting composition.', '2006-03-31 17:34:02.000000', NULL, 1),
(2276978, 310792, 4551, '<td valign="top">Something I see every day but never think about shooting. Nice use of light and color to give depth and dimension to the shot. Excellent tonal range.</td>', 'Something I see every day but never think about shooting. Nice use of light and color to give depth and dimension to the shot. Excellent tonal range.', '2006-03-31 17:36:14.000000', NULL, 1),
(2276985, 312737, 4551, '<td valign="top">I''d like to be more helpful but with the small image I cannot really teel what you are presenting.</td>', 'I''d like to be more helpful but with the small image I cannot really teel what you are presenting.', '2006-03-31 17:41:07.000000', NULL, 1),
