INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2289207, 312516, 40679, '<td valign="top">great job San!! :D</td>', 'great job San!! :D', '2006-04-05 10:35:23.000000', NULL, 0),
(2289304, 311503, 42826, '<td valign="top">look at that awesome placement!!!  Great job!</td>', 'look at that awesome placement!!!  Great job!', '2006-04-05 11:22:17.000000', NULL, 0),
(2289345, 313140, 36382, '<td valign="top">I''m so surprised this did so well.  <br/> <br/>Artfully arranged some construction paper on glass and tissue paper with a table lamp underneath.  My plan was to light it from underneath, to get some cool looking shadows on the paper.  <br/> <br/>However, the shadows looked too dark and ugly and the texture of the paper didn''t come out at all like I had hoped.  This is actually a kind of test shot I took while it was still daylight so you can''t really tell the light from underneath.  <br/> <br/>Maybe next time, I''ll try it with more expensive paper and maybe just plain white paper so that the shadows are the main feature, not the colours.</td>', 'I''m so surprised this did so well.   Artfully arranged some construction paper on glass and tissue paper with a table lamp underneath.  My plan was to light it from underneath, to get some cool looking shadows on the paper.   However, the shadows looked too dark and ugly and the texture of the paper didn''t come out at all like I had hoped.  This is actually a kind of test shot I took while it was still daylight so you can''t really tell the light from underneath.   Maybe next time, I''ll try it with more expensive paper and maybe just plain white paper so that the shadows are the main feature, not the colours.', '2006-04-05 11:39:44.000000', NULL, 0),
(2289402, 311503, 36382, '<td valign="top">Congrats.  Beautiful picture.  I suspected this might be you because of the other beautiful picture in your portfolio.  Thought it might have been a ribbon for you though.</td>', 'Congrats.  Beautiful picture.  I suspected this might be you because of the other beautiful picture in your portfolio.  Thought it might have been a ribbon for you though.', '2006-04-05 12:09:07.000000', NULL, 0),
