(2759238, 312516, 33515, '<td valign="top">Great looking abstract, the colors are wonderful.</td>', 'Great looking abstract, the colors are wonderful.', '2006-08-25 09:53:06.000000', NULL, 0),
(2768157, 312504, 60862, '<td valign="top">I''ll ring as another person who had to look several times to see that the "drops" are actually holes as opposed to sticking up from the metal surface.<br/> <br/>Really great creativity to see that this would be interesting.  Like other shots in your portfolio, this shot shows that you''re far from locked into "stand straight and shoot what''s in front of you" - you really find interesting angles and ways to fill the frame.<br/> <br/>And that''s why this is going in my favorites and you''re going on my favorite photogs list. :)</td>', 'I''ll ring as another person who had to look several times to see that the "drops" are actually holes as opposed to sticking up from the metal surface. Really great creativity to see that this would be interesting.  Like other shots in your portfolio, this shot shows that you''re far from locked into "stand straight and shoot what''s in front of you" - you really find interesting angles and ways to fill the frame. And that''s why this is going in my favorites and you''re going on my favorite photogs list. :)', '2006-08-28 15:27:50.000000', NULL, 0),
(2770379, 312749, 22598, '<td valign="top">Most impressive and creative.  Thanks for sharing!</td>', 'Most impressive and creative.  Thanks for sharing!', '2006-08-29 12:41:31.000000', NULL, 0),
(2794580, 312516, 36999, '<td valign="top">Love the bold color in this image.  In the thumbnail it looks like sand blowing in the wind in a group of sand dunes!</td>', 'Love the bold color in this image.  In the thumbnail it looks like sand blowing in the wind in a group of sand dunes!', '2006-09-04 03:09:01.000000', NULL, 0),
